"""Source-specific, manually reviewed City Ride observations; presentation is derived."""
from pathlib import Path
import json
P=Path(__file__).resolve().parents[1]/'reports/cityride'
def read(f):return json.loads((P/f).read_text())
def save(f,d):(P/f).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
doc=read('shots.json');original=read('review/shots-measured.json')
